  metadata = '{"document_type":"compliance_checklist","category":"professional","use_cases":["Regulatory compliance","Security certifications","Internal audits"],"supported_views":["kanban","wiki","dashboard"],"schema_fields":[{"field_key":"status","field_label":"Status","field_type":"select","options":["draft","in_progress","done"],"ai_fill_enabled":true},{"field_key":"due_date","field_label":"Due","field_type":"date","ai_fill_enabled":true},{"field_key":"owner","field_label":"Owner","field_type":"text","ai_fill_enabled":true},{"field_key":"summary","field_label":"Summary","field_type":"textarea","ai_fill_enabled":true},{"field_key":"origin","field_label":"Origin","field_type":"relation","ai_fill_enabled":false},{"field_key":"framework","field_label":"Framework","field_type":"select","options":["gdpr","soc2","hipaa","iso27001","pci_dss","other"],"ai_fill_enabled":true},{"field_key":"compliance_status","field_label":"Compliance status","field_type":"status","options":[{"value":"not_started","label":"Not started","category":"unstarted"},{"value":"in_progress","label":"In progress","category":"started"},{"value":"compliant","label":"Compliant","category":"completed"},{"value":"non_compliant","label":"Non-compliant","category":"canceled"}],"ai_fill_enabled":true},{"field_key":"related_audit","field_label":"Related audit","field_type":"relation","ai_fill_enabled":false}],"default_properties":{"status":"draft","compliance_status":"not_started"}}'::jsonb
