xplanation]"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Outlook"}]},{"type":"paragraph","content":[{"type":"text","text":"What you expect next period, and any risks to that outlook.","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"type":"text","text":"[Outlook.]"}]}]}'::jsonb,
