update templates
set
  name = 'Research Paper',
  description = 'Abstract, related work, methodology, results, discussion, and references',
  structure_json = '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Abstract"}]},{"type":"paragraph","content":[{"type":"text","text":"The whole paper in 150-250 words — problem, method, key result.","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"type":"text","text":"[Abstract.]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Introduction"}]},{"type":"paragraph","content":[{"type":"text","text":"The gap in existing knowledge this paper addresses.","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"type":"text","text":"[Introduction.]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Related Work & Literature Review"}]},{"type":"paragraph","content":[{"type":"text","text":"Place this work in the current research discourse — prior art and how you differ.","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"type":"text","text":"[Related work.]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Methodology"}]},{"type":"paragraph","content":[{"type":"text","text":"How the research was conducted, in enough detail to replicate.","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"type":"text","text":"[Methodology.]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Results"}]},{"type":"paragraph","content":[{"type":"text","text":"What was found — data and observations, without interpretation yet.","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"type":"text","text":"[Results.]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Discussion"}]},{"type":"paragraph","content":[{"type":"text","text":"What the results mean and their implications. Explicitly disclose study limitations — peer reviewers expect this.","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"type":"text","text":"[Discussion.]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"References"}]},{"type":"paragraph","content":[{"type":"text","text":"Every source cited, formatted per the target venue''s style.","marks":[{"type":"italic"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"[Reference]"}]}]}]}]}'::jsonb,
