  and workspace_id is null;

update templates
set
  name = 'Thesis',
  description = 'Abstract, research question, literature review, methodology, findings, and defense prep',
  structure_json = '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Abstract"}]},{"type":"paragraph","content":[{"type":"text","text":"The thesis in miniature — question, method, and conclusion.","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"type":"text","text":"[Abstract.]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Introduction & Research Question"}]},{"type":"paragraph","content":[{"type":"text","text":"Why this question matters, and precisely what it is.","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"type":"text","text":"[Introduction and research question.]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Literature Review"}]},{"type":"paragraph","content":[{"type":"text","text":"What''s already known, and where this thesis fits. Use H3/H4 subheadings to chapter long sections.","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"type":"text","text":"[Literature review.]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Methodology"}]},{"type":"paragraph","content":[{"type":"text","text":"How the research question was investigated. Use H3/H4 for chapter structure.","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"type":"text","text":"[Methodology.]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Findings"}]},{"type":"paragraph","content":[{"type":"text","text":"What the research revealed. Use H3/H4 for chapter structure.","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"type":"text","text":"[Findings.]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Conclusion & Future Work"}]},{"type":"paragraph","content":[{"type":"text","text":"What this means, and what''s left to explore.","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"type":"text","text":"[Conclusion and future work.]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Defense Notes & Q&A Prep"}]},{"type":"paragraph","content":[{"type":"text","text":"Likely examiner questions, counterarguments, and your prepared responses.","marks":[{"type":"italic"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"[Question / counterargument] — [Response]"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"References"}]},{"type":"paragraph","content":[{"type":"text","text":"Every source cited.","marks":[{"type":"italic"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"[Reference]"}]}]}]}]}'::jsonb,
  metadata = '{"document_type":"thesis","category":"professional","use_cases":["Bachelor thesis","Master thesis","PhD dissertations"],"supported_views":["wiki","kanban","gantt"],"schema_fields":[{"field_key":"status","field_label":"Status","field_type":"select","options":["draft","in_progress","done"],"ai_fill_enabled":true},{"field_key":"due_date","field_label":"Due","field_type":"date","ai_fill_enabled":true},{"field_key":"owner","field_label":"Owner","field_type":"text","ai_fill_enabled":true},{"field_key":"summary","field_label":"Summary","field_type":"textarea","ai_fill_enabled":true},{"field_key":"origin","field_label":"Origin","field_type":"relation","ai_fill_enabled":false},{"field_key":"thesis_level","field_label":"Thesis level","field_type":"select","options":["bachelor","master","phd"],"ai_fill_enabled":true},{"field_key":"thesis_status","field_label":"Thesis status","field_type":"status","options":[{"value":"proposal","label":"Proposal","category":"unstarted"},{"value":"writing","label":"Writing","category":"started"},{"value":"review","label":"Review","category":"started"},{"value":"defense_scheduled","label":"Defense scheduled","category":"started"},{"value":"completed","label":"Completed","category":"completed"}],"ai_fill_enabled":true},{"field_key":"advisor","field_label":"Advisor","field_type":"relation","ai_fill_enabled":false},{"field_key":"defense_date","field_label":"Defense date","field_type":"date","ai_fill_enabled":true},{"field_key":"citation_style","field_label":"Citation style","field_type":"select","options":["apa","mla","chicago","ieee"],"ai_fill_enabled":true}],"default_properties":{"status":"draft","thesis_level":"bachelor","thesis_status":"proposal"}}'::jsonb
