  structure_json = '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Research Question / Scope"}]},{"type":"paragraph","content":[{"type":"text","text":"Document exact search strings, databases (Scholar, IEEE, Scopus), and inclusion/exclusion criteria so the review is replicable.","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"type":"text","text":"[Research question and scope.]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Sources Reviewed"}]},{"type":"paragraph","content":[{"type":"text","text":"Every source, with its key finding and relevance to your question.","marks":[{"type":"italic"}]}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Source"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Key Findings"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Relevance"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"[Source]"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"[Key finding]"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"[Relevance]"}]}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Synthesis & Themes"}]},{"type":"paragraph","content":[{"type":"text","text":"The patterns and disagreements across sources — not a list, a synthesis.","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"type":"text","text":"[Synthesis and themes.]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Gaps in Literature"}]},{"type":"paragraph","content":[{"type":"text","text":"What''s missing — this is often where your own research question lives.","marks":[{"type":"italic"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"[Gap]"}]}]}]}]}'::jsonb,
