insert into templates (name, description, structure_json, is_system, is_shared, slug, metadata)
select
  'Ticket',
  'Lightweight work item for Kanban — context, acceptance criteria, and notes',
  '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Context"}]},{"type":"paragraph","content":[{"type":"text","text":"What needs doing, why it matters, and any links (bug report, brief, PRD). Keep this short — the board card is the unit of work.","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"type":"text","text":"[Context.]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Acceptance Criteria"}]},{"type":"paragraph","content":[{"type":"text","text":"Done-when conditions. Prefer checkable bullets so reviewers share one definition of done.","marks":[{"type":"italic"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"[Criterion]"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"[Criterion]"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Notes & Links"}]},{"type":"paragraph","content":[{"type":"text","text":"Implementation notes, screenshots, or links to PRs and related docs.","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"type":"text","text":"[Notes.]"}]}]}'::jsonb,
  true,
  true,
  'ticket',
  '{"document_type":"ticket","category":"essentials","use_cases":["Engineering backlog tickets","Marketing task cards","Ops / support work items"],"supported_views":["kanban","calendar","gantt","wiki"],"schema_fields":[{"field_key":"status","field_label":"Status","field_type":"select","options":["draft","in_progress","done"],"ai_fill_enabled":true},{"field_key":"due_date","field_label":"Due","field_type":"date","ai_fill_enabled":true},{"field_key":"owner","field_label":"Owner","field_type":"text","ai_fill_enabled":true},{"field_key":"summary","field_label":"Summary","field_type":"textarea","ai_fill_enabled":true},{"field_key":"origin","field_label":"Origin","field_type":"relation","ai_fill_enabled":false},{"field_key":"priority","field_label":"Priority","field_type":"select","options":["urgent","high","medium","low"],"ai_fill_enabled":true},{"field_key":"ticket_type","field_label":"Ticket type","field_type":"select","options":["task","bug","chore","request","spike"],"ai_fill_enabled":true}],"default_properties":{"status":"draft","priority":"medium","ticket_type":"task"}}'::jsonb
where not exists (
  select 1 from templates
  where slug = 'ticket'
    and coalesce(is_system, false) = true
    and workspace_id is null
);

-- Promote person/org text fields to relation where they already exist.
update metadata_schemas
set field_type = 'relation', ai_fill_enabled = false
where field_key in ('employee', 'manager', 'participant', 'recipient', 'counterparty', 'advisor')
  and field_type = 'text';

-- Jurisdiction: text → select (options may already be set by seed).
update metadata_schemas
set field_type = 'select',
    options = coalesce(options, '["DE","EU","US","UK","other"]'::jsonb)
where field_key = 'jurisdiction'
  and field_type = 'text';

-- Department / research_area: text → select when present.
update metadata_schemas
set field_type = 'select',
    options = coalesce(options, '["engineering","product","marketing","operations","leadership","other"]'::jsonb)
where field_key = 'department'
  and field_type = 'text';

update metadata_schemas
set field_type = 'select',
    options = coalesce(
      options,
      '["ai_ml","ux_strategy","growth_economics","product","security","other"]'::jsonb
    )
where field_key = 'research_area'
  and field_type = 'text';

insert into metadata_schemas (workspace_id, field_key, field_label, field_type, options, ai_fill_enabled)
select ms.workspace_id, v.field_key, v.field_label, v.field_type, v.options, v.ai_fill_enabled
from (
  select distinct workspace_id from metadata_schemas
  where field_key in (
    'letter_type', 'requires_hr_followup', 'pdp_status', 'seniority', 'review_status',
    'legal_status', 'compliance_status', 'report_type', 'paper_status', 'thesis_status',
    'essay_status', 'citation_style', 'status'
  )
) ms
cross join (
  values
    ('subject_line', 'Subject line', 'text', null::jsonb, true),
    ('visibility', 'Visibility', 'select', '["private","managers","hr"]'::jsonb, false),
    ('related_audit', 'Related audit', 'relation', null::jsonb, false),
    ('priority', 'Priority', 'select', '["urgent","high","medium","low"]'::jsonb, true),
    ('ticket_type', 'Ticket type', 'select', '["task","bug","chore","request","spike"]'::jsonb, true),
    ('manager', 'Manager', 'relation', null::jsonb, false),
    ('counterparty', 'Counterparty', 'relation', null::jsonb, false)
) as v(field_key, field_label, field_type, options, ai_fill_enabled)
where not exists (
  select 1 from metadata_schemas e
  where e.workspace_id = ms.workspace_id and e.field_key = v.field_key
);
